#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.onbashira_Evoke)]
    public class Onbashira_Evoke : ContraptionEvokeBehaviour
    {
        public Onbashira_Evoke(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Evoke(Entity entity)
        {
            base.Evoke(entity);
            var level = entity.Level;
            var column = entity.GetColumn();
            var columnCount = level.GetMaxLaneCount();
            for (int lane = 0; lane < columnCount; lane++)
            {
                var grid = level.GetGrid(column, lane);
                if (grid == null)
                    continue;
                var positionOffset = Vector3.up * (HEIGHT_PER_LANE * (Mathf.Min(lane, columnCount - 1 - lane)));
                entity.Spawn(VanillaContraptionID.onbashira, grid.GetEntityPosition() + positionOffset);
            }
        }
        public const float HEIGHT_PER_LANE = 400;
    }
}
